package dao;import model.*;import java.sql.*;import java.util.*;
public class MovieDAO5 extends DAO5 {public MovieDAO5(Connection c){super(c);}public Movie5[] getMovies()throws Exception{return query(Movie5.class,"SELECT * FROM tblMovie5 ORDER BY id DESC").toArray(new Movie5[0]);}public Movie5[] getMoviesOnSale()throws Exception{return query(Movie5.class,"SELECT m.* FROM tblMovie5 m WHERE EXISTS (SELECT 1 FROM tblScreening5 s WHERE s.tblMovie5id=m.id AND s.TrangThai='MO_BAN' AND s.GioBatDau>NOW())").toArray(new Movie5[0]);}public Movie5 get(int id)throws Exception{List<Movie5> a=query(Movie5.class,"SELECT * FROM tblMovie5 WHERE id=?",id);if(a.isEmpty())throw new IllegalArgumentException("Không tìm thấy phim");return a.get(0);}public boolean saveMovie(Movie5 m)throws Exception{if(m.getTenPhim()==null||m.getTenPhim().isBlank()||m.getThoiLuong()<=0)throw new IllegalArgumentException("Tên phim và thời lượng phải hợp lệ");m.setMaPhim("P"+UUID.randomUUID().toString().replace("-", "").substring(0,20));m.setId(insert("INSERT INTO tblMovie5(MaPhim,TenPhim,TacGia,ThoiLuong,MoTa,TheLoai,ApPhich,NgayPhatHanh) VALUES(?,?,?,?,?,?,?,?)",m.getMaPhim(),m.getTenPhim().trim(),m.getTacGia(),m.getThoiLuong(),m.getMoTa(),m.getTheLoai(),m.getApPhich(),m.getNgayPhatHanh()));return true;}}
